import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

async function createTask(server: Running, title: string): Promise<Task> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  return ((await response.json()) as { task: Task }).task;
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

function remove(server: Running, id: number | string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
}

describe("SL-006 delete a task permanently", () => {
  describe("AC-1: an existing task is deleted and stays gone after a restart", () => {
    const dbPath = newDbPath();
    let server: Running | undefined;

    after(async () => {
      await server?.stop();
    });

    it("AC-1: DELETE answers 204, the task leaves the list and does not return after kill -9", async () => {
      server = await startServer(dbPath);
      const doomed = await createTask(server, "Buy milk");
      const kept = await createTask(server, "Walk the dog");

      const response = await remove(server, doomed.id);
      assert.equal(response.status, 204);
      assert.deepEqual((await listTasks(server)).map((t) => t.id), [kept.id]);

      await server.stop();
      server = await startServer(dbPath);
      assert.deepEqual((await listTasks(server)).map((t) => t.id), [kept.id]);
    });
  });

  describe("AC-2: a task that does not exist", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: deleting an unknown id answers 404 not_found", async () => {
      const response = await remove(server, 9999);
      assert.equal(response.status, 404);
      const body = (await response.json()) as { error: { code: string; message: string } };
      assert.equal(body.error.code, "not_found");
      assert.equal(typeof body.error.message, "string");
    });

    it("AC-2: deleting the same task twice answers 404 the second time", async () => {
      const task = await createTask(server, "Once");
      assert.equal((await remove(server, task.id)).status, 204);
      assert.equal((await remove(server, task.id)).status, 404);
    });

    it("AC-2: a malformed id answers 404 and deletes nothing", async () => {
      const task = await createTask(server, "Stays");
      assert.equal((await remove(server, "abc")).status, 404);
      assert.equal((await remove(server, "1.5")).status, 404);
      assert.ok((await listTasks(server)).some((t) => t.id === task.id));
    });
  });

  describe("AC-1: the page asks for a browser confirmation first", () => {
    let script: string;
    let server: Running;

    before(async () => {
      server = await startServer();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the script confirms before sending DELETE /api/tasks/:id", () => {
      assert.match(script, /confirm\(/);
      assert.match(script, /method:\s*["']DELETE["']/);
      assert.ok(script.indexOf("confirm(") < script.indexOf("DELETE"));
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
